const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const northernTablelands = ee.Geometry.Point([151.5, -30.5]).buffer(50000); // 50km radius
  const targetDate = '2025-08-02';
  const startDate = '2025-08-01';
  const endDate = '2025-08-03';

  // 2. Data Acquisition & Check - Try Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(northernTablelands)
    .filterDate(startDate, endDate);

  let collectionSize = await collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try MODIS Terra Snow Cover as fallback
    collection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterBounds(northernTablelands)
      .filterDate(startDate, endDate);

    collectionSize = await collection.size().getInfo();
    console.log(`MODIS Terra images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('No satellite data available for August 2, 2025');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use MODIS snow cover data
    const image = collection.first();
    const snowCover = image.select('NDSI_Snow_Cover');

    const stats = await snowCover.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: northernTablelands,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const pixelCount = stats.NDSI_Snow_Cover_count;
    const meanSnow = stats.NDSI_Snow_Cover_mean;

    if (!pixelCount || pixelCount === 0) {
      console.log('No valid pixels after processing');
      console.log('<answer>C2</answer>');
      return;
    }

    console.log(`Valid pixels: ${pixelCount}, Mean NDSI: ${meanSnow ? meanSnow.toFixed(2) : 'null'}`);

    if (meanSnow === null || meanSnow === undefined || isNaN(meanSnow)) {
      console.log('<answer>C3</answer>');
      return;
    }

    // MODIS NDSI_Snow_Cover: 0-100 scale, >10 indicates snow
    if (meanSnow > 10) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }
    return;
  }

  // 3. Process Sentinel-2 data
  const masked = collection.map(maskS2clouds);
  const image = masked.first();

  // 4. Calculate NDSI for snow detection
  const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');

  const stats = await ndsi.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernTablelands,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = stats.NDSI_count;
  const meanNDSI = stats.NDSI_mean;

  if (!pixelCount || pixelCount === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  console.log(`Valid pixels: ${pixelCount}, Mean NDSI: ${meanNDSI ? meanNDSI.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  if (meanNDSI === null || meanNDSI === undefined || isNaN(meanNDSI)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // NDSI > 0.4 typically indicates snow presence
  if (meanNDSI > 0.4) {
    console.log('Snow detected (NDSI > 0.4)');
    console.log('<answer>A</answer>');
  } else {
    console.log('No snow detected (NDSI <= 0.4)');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
